# Scheduled pre-slate dispatcher (master plan F0; owner decision O1, approved 2026-10-13).
#
# Called hourly by the Task Scheduler wrapper scripts/ops/ffball_dispatch.cmd (generated by
# scripts/ops_setup.R). From the NFL schedule and archive/prediction_manifest.csv it decides
# whether a run is due (R/live/dispatch.R). If one is, and ONLY on a clean code tree:
#   1. Rscript scripts/weekly_run.R <season> <week> --commit      (local commit of the prediction manifests)
#   2. Rscript scripts/valuation_run.R <season> <week> --capture   (all-position ESPN capture; one request)
#   3. a local commit of the changed archive/valuation_*.csv manifests (pathspec-limited)
# It then writes data/ops/status.txt and appends data/ops/dispatch_log.csv (both git-ignored).
# It never pushes, never stashes and never touches uncommitted work: a dirty tree is logged and skipped.
#
# Usage (from the project root):
#   Rscript scripts/ops_dispatch.R                                     # decide and, if due, run
#   Rscript scripts/ops_dispatch.R --dry-run                           # decide and report only
#   Rscript scripts/ops_dispatch.R --dry-run --now=2026-10-18T14:30:00Z   # decision at another moment

suppressPackageStartupMessages(
  for (f in list.files("R", pattern = "[.]R$", recursive = TRUE, full.names = TRUE)) source(f)
)
args <- commandArgs(trailingOnly = TRUE)
dry <- "--dry-run" %in% args
now_arg <- sub("^--now=", "", args[startsWith(args, "--now=")])
if (length(now_arg) && !dry) stop("--now is only allowed together with --dry-run.")
now <- if (length(now_arg)) as.POSIXct(now_arg, format = "%Y-%m-%dT%H:%M:%SZ", tz = "UTC") else Sys.time()
if (is.na(now)) stop("--now must look like 2026-10-18T14:30:00Z")
season <- nfl_season(now)
dir.create(file.path(DISPATCH_ROOT, "logs"), recursive = TRUE, showWarnings = FALSE)

rscript_path <- function() {
  p <- file.path(R.home("bin"), if (.Platform$OS.type == "windows") "Rscript.exe" else "Rscript")
  if (file.exists(p)) p else "Rscript"
}

#' Commit the valuation manifests a capture run changed (only those paths; never pushes).
commit_valuation_manifests <- function(season, week) {
  st <- system2("git", c("status", "--porcelain", "--", "archive"), stdout = TRUE)
  changed <- grep("^archive/valuation_[a-z_]+[.]csv$", trimws(substring(st, 4)), value = TRUE)
  if (!length(changed)) return("unchanged")
  system2("git", c("add", "--", changed))
  msg <- sprintf("Valuation capture %d W%d (scheduled run; all positions)", season, week)
  code <- system2("git", c("commit", "-q", "-m", shQuote(msg), "--", changed))
  if (identical(as.integer(code), 0L)) "committed locally" else sprintf("commit FAILED (exit %s)", code)
}

main <- function() {
  sched <- tryCatch(latest_live_file("schedules", season, now), error = function(e) NA_character_)
  age_h <- if (is.na(sched)) Inf else
    as.numeric(difftime(now, parse_utc_stamp(sub("^retrieved_at=(.*)[.]parquet$", "\\1", basename(sched))), units = "hours"))
  if (age_h > 72 && !dry) {
    # nflverse schedule (GitHub release), not ESPN: kickoff times can move (flexed games)
    sched <- tryCatch(fetch_live_nflverse("schedules", season), error = function(e) sched)
  }
  if (is.na(sched)) stop("No live schedule for ", season, "; run scripts/weekly_run.R once.")
  tg <- clean_team_games(sched, read_project_config()$season_type)
  runs <- dispatch_runs()
  log <- read_dispatch_log()
  dec <- dispatch_decision(now, tg, season, runs, log)
  result <- "-"
  status <- 0L
  if (dec$action == "run" && !dry) {
    g <- git_state()
    if (!isFALSE(g$dirty)) {
      result <- "SKIPPED: tracked code has uncommitted changes (never stashed); commit to re-enable runs"
      status <- 2L
    } else {
      stamp <- utc_stamp(now)
      wlog <- file.path(DISPATCH_ROOT, "logs", paste0(stamp, "_weekly_run.log"))
      code1 <- system2(rscript_path(), c("scripts/weekly_run.R", season, dec$week, "--commit"), stdout = wlog, stderr = wlog)
      if (!identical(as.integer(code1), 0L)) {
        result <- sprintf("weekly_run FAILED (exit %s; see %s)", code1, wlog)
        status <- 1L
      } else {
        vlog <- file.path(DISPATCH_ROOT, "logs", paste0(stamp, "_valuation_capture.log"))
        code2 <- system2(rscript_path(), c("scripts/valuation_run.R", season, dec$week, "--capture"), stdout = vlog, stderr = vlog)
        committed <- commit_valuation_manifests(season, dec$week)
        result <- sprintf("weekly_run ok (manifests committed locally); valuation capture %s; valuation manifests %s",
                          if (identical(as.integer(code2), 0L)) "ok" else sprintf("FAILED (exit %s; see %s)", code2, vlog),
                          committed)
        if (!identical(as.integer(code2), 0L)) status <- 1L
      }
    }
  }
  if (!dry) {
    append_manifest(tibble::tibble(
      logged_at_utc = format(Sys.time(), "%Y-%m-%dT%H:%M:%SZ", tz = "UTC"),
      decided_for_utc = format(now, "%Y-%m-%dT%H:%M:%SZ", tz = "UTC"),
      action = dec$action, kind = dec$kind %||% NA_character_, season = season, week = dec$week,
      slate_id = dec$slate_id, reason = dec$reason, result = result
    ), DISPATCH_LOG)
  }
  week <- if (is.na(dec$week)) infer_target_week(tg, season, now) else dec$week
  runs <- dispatch_runs()
  cov <- if (is.na(week)) NULL else
    tryCatch(post_report_coverage(season, week, tg, runs, now), error = function(e) NULL)
  log <- read_dispatch_log()
  last <- if (!is.null(log) && any(log$action == "run")) {
    r <- utils::tail(log[log$action == "run", ], 1)
    sprintf("%s %s: %s", r$decided_for_utc, r$slate_id, r$result)
  } else NULL
  lines <- dispatch_status_lines(now, dec, cov, capture_cadence(season),
                                 tryCatch(git_sync_state(), error = function(e) NULL), last)
  if (dry) lines[1] <- paste(lines[1], "[DRY RUN]")
  if (!dry) writeLines(lines, DISPATCH_STATUS)
  # console (the wrapper's log): everything for runs and dry runs, one line for hourly no-ops
  if (dry || dec$action == "run") cat(lines, sep = "\n") else cat(sprintf("%s none: %s\n", fmt_utc(now), dec$reason))
  status
}

status <- 0L
if (!dry && !dispatch_lock(now = now)) {
  cat("Another dispatcher run holds", DISPATCH_LOCK, "- exiting.\n")
} else {
  status <- tryCatch(main(), error = function(e) {
    cat("Dispatcher error:", conditionMessage(e), "\n")
    if (!dry) try(writeLines(c(sprintf("FFball dispatcher status - %s", fmt_utc(Sys.time())),
                               paste("ERROR:", conditionMessage(e))), DISPATCH_STATUS))
    3L
  }, finally = if (!dry) dispatch_unlock())
}
quit(save = "no", status = status)
